// Scenario 3: user-facing query embedding path.
//
// POST /v1/feedback-records/search/semantic is synchronous: Hub embeds the
// query through TEI and runs a pgvector similarity lookup before responding.
// Latency here is what users feel when they search.
//
// Profiles let you measure the same endpoint in three TEI states:
//   - warm    : low concurrency, TEI warm and idle
//   - cold    : single request after a TEI rollout (use with run-cold-start.sh)
//   - busy    : steady search load — meant to be run CONCURRENTLY with the
//               enrichment scenario in another process, to measure how search
//               latency degrades when workers are hammering the same TEI pod.
//
// Required env:
//   HUB_URL       — Hub base URL
//   HUB_API_KEY   — bearer token
//
// Optional env:
//   TENANT_ID     — defaults to formbricks-hub-test-tenant
//   PROFILE       — smoke | warm | cold | busy (default: smoke)
//   LIMIT         — search result limit (default 10)
//   MIN_SCORE     — minimum similarity (default 0.5)
//
// Run:
//   k6 run -e HUB_URL=... -e HUB_API_KEY=... -e PROFILE=warm k6/hub-search.js

import http from "k6/http";
import { check } from "k6";
import { Trend } from "k6/metrics";
import { pickQuery } from "./lib/payloads.js";
import { buildSummary } from "./lib/summary.js";

const HUB_URL = __ENV.HUB_URL;
const HUB_API_KEY = [REDACTED];
const TENANT_ID = __ENV.TENANT_ID || "formbricks-hub-test-tenant";
const PROFILE = __ENV.PROFILE || "smoke";
const LIMIT = Number(__ENV.LIMIT || 10);
const MIN_SCORE = Number(__ENV.MIN_SCORE || 0.5);

if (!HUB_URL) throw new Error("HUB_URL is required");
if (!HUB_API_KEY) throw new Error("HUB_API_KEY is required");

const searchLatency = new Trend("search_latency", true);

const PROFILES = {
  smoke: {
    scenarios: {
      smoke: { executor: "per-vu-iterations", vus: 1, iterations: 6, maxDuration: "30s" },
    },
  },
  warm: {
    scenarios: {
      warm: {
        executor: "constant-arrival-rate",
        rate: 2,
        timeUnit: "1s",
        duration: "5m",
        preAllocatedVUs: 5,
        maxVUs: 20,
      },
    },
  },
  // Single-shot, used by run-cold-start.sh right after a TEI restart.
  cold: {
    scenarios: {
      cold: { executor: "per-vu-iterations", vus: 1, iterations: 1, maxDuration: "60s" },
    },
  },
  // Sustained background search load — run alongside hub-enrichment.js.
  busy: {
    scenarios: {
      busy: {
        executor: "constant-arrival-rate",
        rate: 5,
        timeUnit: "1s",
        duration: "15m",
        preAllocatedVUs: 10,
        maxVUs: 50,
      },
    },
  },
};

const profile = PROFILES[PROFILE];
if (!profile) throw new Error(`unknown PROFILE: ${PROFILE}`);

export const options = {
  ...profile,
  thresholds: {
    http_req_failed: ["rate<0.01"],
    http_req_duration: ["p(95)<3000"],
  },
};

export default function () {
  const q = pickQuery(TENANT_ID);
  const url = `${HUB_URL}/v1/feedback-records/search/semantic?limit=${LIMIT}&min_score=${MIN_SCORE}`;
  const res = http.post(
    url,
    JSON.stringify({ query: q.query, tenant_id: q.tenant_id }),
    {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${HUB_API_KEY}`,
      },
      tags: { endpoint: "hub_search", lang: q.lang },
    },
  );

  check(res, {
    "status 200": (r) => r.status === 200,
    "has results array": (r) => {
      try {
        const j = r.json();
        return j && (Array.isArray(j.results) || Array.isArray(j.data) || Array.isArray(j));
      } catch (_) {
        return false;
      }
    },
  });

  searchLatency.add(res.timings.duration);
}

export function handleSummary(data) {
  return buildSummary(data, {
    scenario: `hub-search/${PROFILE}`,
    criteria: { maxFailRate: 0.01 },
  });
}

// Scenario: web-mediated survey-generation.
//
// Drives the one Formbricks AI feature that is reachable via a real HTTP
// route: POST /api/v3/surveys/generate. The web app validates the prompt,
// calls vLLM through its OpenAI-compatible client, parses the response
// against the Zod schema, and returns the survey draft.
//
// This is the only scenario in this suite that measures Next.js/web-pod
// overhead in addition to LLM latency. The other three scenarios isolate
// vLLM.
//
// Production rate limit on this route is 10 requests / minute / organization
// (rateLimitConfigs.api.v3SurveyGenerate). At rates above ~0.16 rps you will
// see 429s — that is expected, and `rate_limited` is recorded separately
// from other errors so the report can distinguish them.
//
// Required env:
//   FORMBRICKS_URL          — e.g. https://app.staging.formbricks.com
//   FORMBRICKS_API_KEY      — fbk_... management API key with readWrite on
//                             the target workspace
//   FORMBRICKS_WORKSPACE_ID — workspace id the API key has access to
//
// Optional env:
//   PROFILE   — smoke | baseline | mid | burst | stress (default: smoke)
//   TIMEOUT   — k6 HTTP timeout, default 60s (Formbricks's Next.js layer
//               caps at ~30s; pad to capture timeout failures)
//   RATE / DURATION / MAX_VUS — override constant-arrival profiles

import http from "k6/http";
import { check } from "k6";
import { Trend, Rate, Counter } from "k6/metrics";
import { pickSurveyGenFixture, surveyGenFixtureCount } from "./lib/payloads.js";
import { buildSummary } from "./lib/summary.js";

const FORMBRICKS_URL = __ENV.FORMBRICKS_URL;
const FORMBRICKS_API_KEY = [REDACTED];
const FORMBRICKS_WORKSPACE_ID = __ENV.FORMBRICKS_WORKSPACE_ID;
const PROFILE = __ENV.PROFILE || "smoke";
const TIMEOUT = __ENV.TIMEOUT || "60s";
const RATE = __ENV.RATE ? Number(__ENV.RATE) : null;
const DURATION = __ENV.DURATION || null;
const MAX_VUS = __ENV.MAX_VUS ? Number(__ENV.MAX_VUS) : null;

if (!FORMBRICKS_URL) throw new Error("FORMBRICKS_URL is required");
if (!FORMBRICKS_API_KEY) throw new Error("FORMBRICKS_API_KEY is required");
if (!FORMBRICKS_WORKSPACE_ID) throw new Error("FORMBRICKS_WORKSPACE_ID is required");
if (surveyGenFixtureCount() === 0) throw new Error("no surveygen fixtures loaded");

const latencyOk = new Trend("latency_ok", true);
const generated = new Rate("generated_ok");
const rateLimited = new Rate("rate_limited");
const aiUnavailable = new Rate("ai_unavailable");
const badGateway = new Rate("bad_gateway");
const otherErrors = new Counter("other_errors");

function constantArrival(rate, duration, maxVUs) {
  return {
    executor: "constant-arrival-rate",
    rate,
    timeUnit: "1s",
    duration,
    preAllocatedVUs: Math.max(2, Math.ceil(rate * 6)),
    maxVUs,
  };
}

const PROFILES = {
  smoke: {
    scenarios: {
      smoke: { executor: "per-vu-iterations", vus: 1, iterations: 3, maxDuration: "3m" },
    },
  },
  // Below the per-org rate limit. Used to characterize warm steady-state.
  baseline: { scenarios: { baseline: constantArrival(RATE ?? 0.1, DURATION ?? "10m", MAX_VUS ?? 10) } },
  // At the per-org rate limit. Expect ~0% 429 if the request rate is tuned
  // exactly at 10/min; bump RATE up to deliberately exercise the limiter.
  mid: { scenarios: { mid: constantArrival(RATE ?? 0.16, DURATION ?? "10m", MAX_VUS ?? 10) } },
  // Deliberately above the limit. The headline metric for this profile is
  // rate_limited — confirms the limiter does what we expect under spikes.
  burst: {
    scenarios: {
      burst: {
        executor: "ramping-arrival-rate",
        startRate: 0,
        timeUnit: "1s",
        preAllocatedVUs: 10,
        maxVUs: MAX_VUS ?? 50,
        stages: [
          { target: 0.1, duration: "1m" },
          { target: 2, duration: "30s" },
          { target: 2, duration: "2m" },
          { target: 0.1, duration: "30s" },
          { target: 0.1, duration: "2m" },
        ],
      },
    },
  },
  // Push hard. We expect mostly 429s; surface anything else (timeouts, 5xx).
  stress: {
    scenarios: {
      stress: {
        executor: "ramping-arrival-rate",
        startRate: 0.5,
        timeUnit: "1s",
        preAllocatedVUs: 20,
        maxVUs: MAX_VUS ?? 100,
        stages: [
          { target: 1, duration: "1m" },
          { target: 5, duration: "1m" },
          { target: 10, duration: "1m" },
          { target: 0, duration: "30s" },
        ],
      },
    },
  },
};

const profile = PROFILES[PROFILE];
if (!profile) throw new Error(`unknown PROFILE: ${PROFILE}`);

export const options = {
  ...profile,
  thresholds: {
    // Don't fail the run when rate-limited responses dominate the mix —
    // they are the expected outcome of the burst/stress profiles.
    other_errors: ["count==0"],
  },
};

export default function () {
  const fixture = pickSurveyGenFixture();
  const body = {
    workspaceId: FORMBRICKS_WORKSPACE_ID,
    prompt: fixture.prompt,
    type: "link",
    language: fixture.preferred_language,
  };

  const res = http.post(`${FORMBRICKS_URL}/api/v3/surveys/generate`, JSON.stringify(body), {
    headers: {
      "Content-Type": "application/json",
      "x-api-key": [REDACTED],
    },
    timeout: TIMEOUT,
    tags: { endpoint: "v3_surveys_generate", fixture: fixture.name, workflow: "survey_gen_web" },
  });

  // Classify the response. The web layer returns documented status codes for
  // each failure class — see route.ts.
  const status = res.status;
  if (status === 200 || status === 201) {
    generated.add(true);
    rateLimited.add(false);
    aiUnavailable.add(false);
    badGateway.add(false);
    latencyOk.add(res.timings.duration);
  } else if (status === 429) {
    generated.add(false);
    rateLimited.add(true);
    aiUnavailable.add(false);
    badGateway.add(false);
  } else if (status === 503) {
    generated.add(false);
    rateLimited.add(false);
    aiUnavailable.add(true);
    badGateway.add(false);
  } else if (status === 502) {
    generated.add(false);
    rateLimited.add(false);
    aiUnavailable.add(false);
    badGateway.add(true);
  } else {
    generated.add(false);
    rateLimited.add(false);
    aiUnavailable.add(false);
    badGateway.add(false);
    otherErrors.add(1);
  }

  check(res, {
    "no surprise status": (r) =>
      r.status === 200 ||
      r.status === 201 ||
      r.status === 400 ||
      r.status === 422 ||
      r.status === 429 ||
      r.status === 502 ||
      r.status === 503,
  });
}

export function handleSummary(data) {
  return buildSummary(data, {
    scenario: `web-survey-gen/${PROFILE}`,
    criteria: {},
  });
}

// Scenario: direct LLM /v1/chat/completions, chart-generation workload.
//
// Prefill-heavy. Large schema context (~2000 tokens of available
// measures/dimensions/chart types) plus a short natural-language prompt →
// small structured query (~200 tokens). This shape stresses the GPU's
// prefill (one big forward pass), not decode.
//
// Mirrors the prompt + decoding parameters that
// apps/web/modules/ee/analysis/charts/actions.ts uses in production:
//   - temperature 0
//   - small output
//   - structured output enforced via response_format
//
// Required env: LLM_URL, MODEL
// Optional env: LLM_API_KEY, PROFILE, RESPONSE_FORMAT, TIMEOUT, MAX_TOKENS,
//   TEMPERATURE, RATE, DURATION, MAX_VUS

import http from "k6/http";
import { check } from "k6";
import { Trend, Rate } from "k6/metrics";
import {
  pickChartGenFixture,
  buildChartGenMessages,
  buildChatCompletionBody,
  CHARTGEN_REQUIRED_KEYS,
} from "./lib/payloads.js";
import { validateStructuredResponse, tokenUsage } from "./lib/validators.js";
import { buildSummary } from "./lib/summary.js";

const LLM_URL = __ENV.LLM_URL;
const MODEL = __ENV.MODEL;
const LLM_API_KEY = [REDACTED] || "";
const PROFILE = __ENV.PROFILE || "smoke";
const RESPONSE_FORMAT = __ENV.RESPONSE_FORMAT || "json_object";
const TIMEOUT = __ENV.TIMEOUT || "120s";
const MAX_TOKENS = Number(__ENV.MAX_TOKENS || 1024);
const TEMPERATURE = Number(__ENV.TEMPERATURE || 0);
const RATE = __ENV.RATE ? Number(__ENV.RATE) : null;
const DURATION = __ENV.DURATION || null;
const MAX_VUS = __ENV.MAX_VUS ? Number(__ENV.MAX_VUS) : null;

if (!LLM_URL) throw new Error("LLM_URL is required");
if (!MODEL) throw new Error("MODEL is required");

const promptTokens = new Trend("prompt_tokens");
const completionTokens = new Trend("completion_tokens");
const tokensPerSec = new Trend("tokens_per_sec");
const schemaValid = new Rate("schema_valid");
const malformedJson = new Rate("malformed_json");
const missingKeys = new Rate("missing_keys");

function constantArrival(rate, duration, maxVUs) {
  return {
    executor: "constant-arrival-rate",
    rate,
    timeUnit: "1s",
    duration,
    preAllocatedVUs: Math.max(2, Math.ceil(rate * 3)),
    maxVUs,
  };
}

const PROFILES = {
  smoke: {
    scenarios: {
      smoke: { executor: "per-vu-iterations", vus: 1, iterations: 3, maxDuration: "3m" },
    },
  },
  baseline: { scenarios: { baseline: constantArrival(RATE ?? 0.5, DURATION ?? "5m", MAX_VUS ?? 10) } },
  mid: { scenarios: { mid: constantArrival(RATE ?? 2, DURATION ?? "5m", MAX_VUS ?? 30) } },
  burst: {
    scenarios: {
      burst: {
        executor: "ramping-arrival-rate",
        startRate: 0,
        timeUnit: "1s",
        preAllocatedVUs: 10,
        maxVUs: MAX_VUS ?? 100,
        stages: [
          { target: 1, duration: "1m" },
          { target: 10, duration: "30s" },
          { target: 10, duration: "2m" },
          { target: 1, duration: "30s" },
          { target: 1, duration: "1m" },
        ],
      },
    },
  },
  stress: {
    scenarios: {
      stress: {
        executor: "ramping-arrival-rate",
        startRate: 0.5,
        timeUnit: "1s",
        preAllocatedVUs: 20,
        maxVUs: MAX_VUS ?? 200,
        stages: [
          { target: 1, duration: "2m" },
          { target: 2, duration: "2m" },
          { target: 4, duration: "2m" },
          { target: 8, duration: "2m" },
          { target: 16, duration: "2m" },
          { target: 0, duration: "30s" },
        ],
      },
    },
  },
};

const profile = PROFILES[PROFILE];
if (!profile) throw new Error(`unknown PROFILE: ${PROFILE}`);

export const options = {
  ...profile,
  thresholds: {
    http_req_failed: ["rate<0.05"],
    schema_valid: ["rate>0.9"],
  },
};

export default function () {
  const fixture = pickChartGenFixture();
  const messages = buildChartGenMessages(fixture);
  const body = buildChatCompletionBody({
    model: MODEL,
    messages,
    expectedKeys: CHARTGEN_REQUIRED_KEYS,
    temperature: TEMPERATURE,
    maxTokens: MAX_TOKENS,
    responseFormat: RESPONSE_FORMAT === "none" ? null : RESPONSE_FORMAT,
  });

  const headers = { "Content-Type": "application/json" };
  if (LLM_API_KEY) headers.Authorization = `Bearer ${LLM_API_KEY}`;

  const res = http.post(`${LLM_URL}/chat/completions`, JSON.stringify(body), {
    headers,
    timeout: TIMEOUT,
    tags: { endpoint: "chat_completions", fixture: fixture.name, workflow: "chart_gen" },
  });

  const ok = check(res, {
    "status 200": (r) => r.status === 200,
    "has choices": (r) => {
      try {
        const j = r.json();
        return j && Array.isArray(j.choices) && j.choices.length > 0;
      } catch (_) {
        return false;
      }
    },
  });

  let parsed = null;
  if (ok) {
    try {
      parsed = res.json();
    } catch (_) {}
  }

  const v = parsed
    ? validateStructuredResponse(parsed, CHARTGEN_REQUIRED_KEYS)
    : { parsed: false, valid: false, missingKeys: CHARTGEN_REQUIRED_KEYS.length };
  schemaValid.add(v.valid);
  malformedJson.add(!v.parsed);
  missingKeys.add(v.parsed && v.missingKeys > 0);

  const usage = parsed ? tokenUsage(parsed) : { prompt: 0, completion: 0 };
  if (usage.prompt > 0) promptTokens.add(usage.prompt);
  if (usage.completion > 0) completionTokens.add(usage.completion);
  if (usage.completion > 0 && res.timings.duration > 0) {
    tokensPerSec.add(usage.completion / (res.timings.duration / 1000));
  }
}

export function handleSummary(data) {
  return buildSummary(data, {
    scenario: `llm-direct-chartgen/${PROFILE}`,
    criteria: { maxFailRate: 0.05, minSchemaValidRate: 0.9 },
  });
}

// Scenario: direct LLM /v1/chat/completions, survey-generation workload.
//
// Decode-heavy. Short prompt (~500 tokens system + a few sentences user) →
// large structured survey JSON (~3000 tokens). This shape stresses the GPU's
// decode loop, not prefill.
//
// Mirrors the prompt + decoding parameters that
// apps/web/app/api/v3/surveys/generate/service.ts uses in production:
//   - temperature 0.2
//   - max_tokens 3000
//   - structured output enforced via response_format
//
// Required env: LLM_URL, MODEL
// Optional env: LLM_API_KEY, PROFILE, RESPONSE_FORMAT, TIMEOUT, MAX_TOKENS,
//   TEMPERATURE, RATE, DURATION, MAX_VUS

import http from "k6/http";
import { check } from "k6";
import { Trend, Rate } from "k6/metrics";
import {
  pickSurveyGenFixture,
  buildSurveyGenMessages,
  buildChatCompletionBody,
  SURVEYGEN_REQUIRED_KEYS,
} from "./lib/payloads.js";
import { validateStructuredResponse, tokenUsage } from "./lib/validators.js";
import { buildSummary } from "./lib/summary.js";

const LLM_URL = __ENV.LLM_URL;
const MODEL = __ENV.MODEL;
const LLM_API_KEY = [REDACTED] || "";
const PROFILE = __ENV.PROFILE || "smoke";
const RESPONSE_FORMAT = __ENV.RESPONSE_FORMAT || "json_object";
const TIMEOUT = __ENV.TIMEOUT || "120s";
const MAX_TOKENS = Number(__ENV.MAX_TOKENS || 3000);
const TEMPERATURE = Number(__ENV.TEMPERATURE != null ? __ENV.TEMPERATURE : 0.2);
const RATE = __ENV.RATE ? Number(__ENV.RATE) : null;
const DURATION = __ENV.DURATION || null;
