  baseline: { scenarios: { baseline: constantArrival(RATE ?? 0.1, DURATION ?? "5m", MAX_VUS ?? 10) } },
  mid: { scenarios: { mid: constantArrival(RATE ?? 0.5, DURATION ?? "5m", MAX_VUS ?? 30) } },
  burst: {
    scenarios: {
      burst: {
        executor: "ramping-arrival-rate",
